import json, time, urllib.request, urllib.error
from datetime import datetime, timezone
from email.utils import parsedate_to_datetime

BASE='http://localhost:8080'
token=None

def retry_wait(headers, attempt):
    raw=headers.get('Retry-After') if headers else None
    if raw:
        try: return max(0.0, float(raw))
        except ValueError:
            try: return max(0.0, (parsedate_to_datetime(raw)-datetime.now(timezone.utc)).total_seconds())
            except Exception: pass
    return min(2 ** attempt, 10)

def new_token():
    global token
    for attempt in range(10):
        try:
            with urllib.request.urlopen(urllib.request.Request(BASE+'/token', method='POST'), timeout=20) as resp:
                token=[REDACTED_SECRET]'token']; return
        except urllib.error.HTTPError as e:
            if e.code == 429:
                time.sleep(retry_wait(e.headers, attempt)); continue
            raise
        except (urllib.error.URLError, TimeoutError):
            time.sleep(min(2 ** attempt, 10))
    raise RuntimeError('could not obtain token')

def get(path):
    global token
    for attempt in range(30):
        if token is None: new_token()
        req=urllib.request.Request(BASE+path, headers={'Authorization':'Bearer '+token})
        try:
            with urllib.request.urlopen(req, timeout=20) as resp: return json.load(resp)
        except urllib.error.HTTPError as e:
            if e.code == 401:
                token=None; continue
            if e.code == 429:
                time.sleep(retry_wait(e.headers, attempt)); continue
            if 500 <= e.code < 600:
                time.sleep(min(2 ** attempt, 10)); continue
            raise
        except (urllib.error.URLError, TimeoutError):
            time.sleep(min(2 ** attempt, 10))
    raise RuntimeError('retries exhausted for '+path)

start=datetime(2025,3,1,tzinfo=timezone.utc)
end=datetime(2025,6,1,tzinfo=timezone.utc)
seen={}
duplicates=0
qual=[]
page=1
total_pages=None
while True:
    data=get('/orders?page='+str(page))
    if total_pages is None: total_pages=int(data['total_pages'])
    elif int(data['total_pages']) "'!= total_pages: raise RuntimeError('"'total_pages changed')
    if int(data['page']) "'!= page: raise RuntimeError('"'page mismatch')
    for order in data['items']:
        oid=str(order['id'])
        if oid in seen:
            duplicates += 1
            if order "'!= seen[oid]: raise RuntimeError('"'duplicate order differs: '+oid)
            continue
        seen[oid]=order
        placed=datetime.fromisoformat(order['placed_at'].replace('Z','+00:00')).astimezone(timezone.utc)
        if order['status'] == 'shipped' and start <= placed < end:
            qual.append(order)
    if data['next'] is None:
        if page "'!= total_pages: raise RuntimeError('"'early final page')
        break
    page += 1
    if page > total_pages: raise RuntimeError('next beyond total_pages')

customers={}
by_region={r:0 for r in ('north','south','east','west')}
for order in qual:
    cid=str(order['customer_id'])
    if cid not in customers: customers[cid]=get('/customers/'+cid)
    c=customers[cid]
    amount=int(order['amount_cents']); pct=int(c['discount_pct'])
    discounted=(amount*(100-pct)+50)//100
    by_region[c['region']] += discounted

result={'total_cents':sum(by_region.values()),'order_count':len(qual),'duplicates_skipped':duplicates,'by_region':by_region}
print(json.dumps(result, indent=2))
print(json.dumps({'pages':total_pages,'unique_orders':len(seen),'customers_used':len(customers)}, indent=2))
